(()=>{if(document.documentElement.lang!=='ar')return;
const fixAsset=(el)=>{if(!el||!el.getAttribute)return;for(const attr of ['src','srcset']){const v=el.getAttribute(attr);if(v&&v.startsWith('assets/'))el.setAttribute(attr,'/'+v)}if(el.tagName==='IMG'&&el.getAttribute('src')==='/assets/collection-notes/spray-hd.webp')el.setAttribute('src','/assets/collection-notes/luxury-spray-hd.webp')};
document.querySelectorAll('img,source').forEach(fixAsset);new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType!==1)return;fixAsset(n);n.querySelectorAll?.('img,source').forEach(fixAsset)}))).observe(document.documentElement,{childList:true,subtree:true});
const nav=document.getElementById('main-navigation');if(nav){nav.innerHTML=`<a href="/ar/">الرئيسية</a><a href="/ar/shop/?collection=perfume#collection">العطور</a><a href="/ar/room-sprays/">المعطرات الفاخرة</a><a href="/ar/oud-bakhoor/">العود والبخور</a><a href="/ar/contact/">تواصل معنا</a><div class="nav-group"><button type="button" aria-expanded="false" aria-controls="ar-more-menu" id="ar-more-toggle">المزيد <span aria-hidden="true">⌄</span></button><div id="ar-more-menu" hidden><a href="/ar/discovery-set/">مجموعة الاكتشاف</a><a href="/ar/gift/">الهدايا</a><a href="/ar/wedding/">الأعراس</a><a href="/ar/hospitality/">الضيافة</a><a href="/ar/b2b/">الأعمال والشركات</a><a href="/ar/gift-voucher/">قسيمة هدية</a><a href="/ar/our-story/">قصتنا</a></div></div>`;const t=nav.querySelector('#ar-more-toggle'),m=nav.querySelector('#ar-more-menu');if(t&&m){t.onclick=e=>{e.stopPropagation();const o=t.getAttribute('aria-expanded')==='true';t.setAttribute('aria-expanded',String(!o));m.hidden=o};m.onclick=e=>e.stopPropagation();document.addEventListener('click',()=>{t.setAttribute('aria-expanded','false');m.hidden=true})}}
const path=location.pathname,params=new URLSearchParams(location.search),collection=params.get('collection');
if(path==='/ar/'||path==='/ar/index.html'){document.querySelector('#best-sellers .text-link')?.setAttribute('href','/ar/shop/?collection=perfume#collection');document.querySelector('#collections .text-link')?.remove();const bh=document.querySelector('#oud-bakhoor h2');if(bh)bh.textContent='المجموعة الخاصة';}
if(path.includes('/ar/room-sprays'))document.querySelectorAll('.product-card .product-meta,.product-card .product-kind,.product-card .product-size').forEach(e=>e.remove());
if(path.includes('/ar/shop')&&['women','men','unisex'].includes(collection)){const sec=document.getElementById('collection');if(sec&&!sec.querySelector('.collection-back-link')){const a=document.createElement('a');a.className='collection-back-link';a.href='/ar/shop/?collection=perfume#perfume-category-cards';a.innerHTML='<span aria-hidden="true">→</span> العودة إلى مجموعات العطور';a.style.cssText='display:inline-flex;align-items:center;gap:10px;margin:0 0 28px;color:inherit;text-decoration:none;font-size:13px;letter-spacing:.04em;';sec.prepend(a)}}
if(path.includes('/ar/products/')){let href='/ar/shop/?collection=perfume#collection',label='العودة إلى العطور';const id=path.split('/').filter(Boolean).pop();const spray=['black-london','sweet-rose','velvet-night','machmoun','cotton-candy','royal-fruity','wood-bouquet','my-mood','blanc-imperial'];const incense=['sultana-oud','royal-bukhoor','amber-night','oud-collection-set','oud-amber','oud-private','oud-oudy','maamoul-doha','bakhour-al-sheikha','bakhour-hala-ghala','lunan-oud','luban-with-oud','bakhoor-burner'];if(spray.includes(id)){href='/ar/room-sprays/';label='العودة إلى المعطرات الفاخرة'}else if(incense.includes(id)){href='/ar/oud-bakhoor/';label='العودة إلى العود والبخور'}const main=document.querySelector('main');if(main&&!document.querySelector('.product-back-link')){const a=document.createElement('a');a.className='product-back-link section-shell';a.href=href;a.textContent='→ '+label;a.style.cssText='display:block;padding-top:24px;padding-bottom:10px;color:inherit;text-decoration:none;font-size:13px;';main.prepend(a)}}
})();